import React, { useState, useEffect } from 'react';
import './App.css';
import translations from './translations/translations.json';

function LoginPage({ onLogin }) {
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [idioma, setIdioma] = useState('pt-BR');

  const t = (chave) => translations[idioma]?.[chave] || chave;

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:3001/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, senha })
      });

      if (!response.ok) throw new Error('Falha no login');

      const data = await response.json();
      localStorage.setItem('token', data.token);
      localStorage.setItem('usuario', JSON.stringify(data.usuario));
      localStorage.setItem('idioma', idioma);
      onLogin(data.usuario);
    } catch (err) {
      alert('Erro no login');
    }
  };

  return (
    <div className="login-container">
      <div className="login-box">
        <div className="language-selector">
          <button onClick={() => setIdioma('pt-BR')} className={idioma === 'pt-BR' ? 'ativo' : ''}>
            🇧🇷 PT
          </button>
          <button onClick={() => setIdioma('ja')} className={idioma === 'ja' ? 'ativo' : ''}>
            🇯🇵 JA
          </button>
          <button onClick={() => setIdioma('en')} className={idioma === 'en' ? 'ativo' : ''}>
            🇺🇸 EN
          </button>
        </div>

        <h1>🏳️ Kaizen Barber Shop</h1>
        <p className="subtitle">{t('login.titulo')}</p>

        <form onSubmit={handleLogin}>
          <input
            type="email"
            placeholder={t('login.email')}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder={t('login.senha')}
            value={senha}
            onChange={(e) => setSenha(e.target.value)}
            required
          />
          <button type="submit">{t('botao.entrar')}</button>
        </form>

        <p className="demo-hint">
          Demo: marco@kaizen.com.br / qualquer senha
        </p>
      </div>
    </div>
  );
}

function DashboardPage({ usuario, idioma, setIdioma }) {
  const [receita, setReceita] = useState(0);
  const [agendamentos, setAgendamentos] = useState(0);

  const t = (chave) => translations[idioma]?.[chave] || chave;

  useEffect(() => {
    fetchDadosDoDia();
  }, []);

  const fetchDadosDoDia = async () => {
    try {
      const hoje = new Date().toISOString().split('T')[0];
      const response = await fetch(`http://localhost:3001/api/relatorios/dia/${hoje}`);
      const data = await response.json();
      setReceita(data.receita_bruta);
      setAgendamentos(data.agendamentos);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="dashboard-container">
      <header className="header">
        <h1>🏳️ Kaizen Barber Shop</h1>
        <div className="header-controls">
          <select value={idioma} onChange={(e) => setIdioma(e.target.value)} className="idioma-select">
            <option value="pt-BR">🇧🇷 Português</option>
            <option value="ja">🇯🇵 日本語</option>
            <option value="en">🇺🇸 English</option>
          </select>
          <span className="usuario-info">{usuario.nome}</span>
        </div>
      </header>

      <nav className="navbar">
        <a href="#dashboard">{t('nav.dashboard')}</a>
        <a href="#agendamentos">{t('nav.agendamentos')}</a>
        <a href="#clientes">{t('nav.clientes')}</a>
        <a href="#profissionais">{t('nav.profissionais')}</a>
      </nav>

      <main className="main-content">
        <section className="cards-container">
          <div className="card">
            <h3>{t('dashboard.receita_hoje')}</h3>
            <p className="numero">¥{receita.toLocaleString('ja-JP')}</p>
          </div>
          <div className="card">
            <h3>{t('dashboard.agendamentos_hoje')}</h3>
            <p className="numero">{agendamentos}</p>
          </div>
          <div className="card">
            <h3>{t('dashboard.profissionais_online')}</h3>
            <p className="numero">3</p>
          </div>
        </section>

        <section className="content-area">
          <h2>{t('dashboard.titulo')}</h2>
          <p>{t('dashboard.bem_vindo')}</p>
        </section>
      </main>
    </div>
  );
}

function App() {
  const [usuario, setUsuario] = useState(null);
  const [idioma, setIdioma] = useState(localStorage.getItem('idioma') || 'pt-BR');

  useEffect(() => {
    const usuarioSalvo = localStorage.getItem('usuario');
    if (usuarioSalvo) {
      setUsuario(JSON.parse(usuarioSalvo));
    }
  }, []);

  const handleLogin = (usuarioData) => {
    setUsuario(usuarioData);
  };

  if (!usuario) {
    return <LoginPage onLogin={handleLogin} />;
  }

  return <DashboardPage usuario={usuario} idioma={idioma} setIdioma={setIdioma} />;
}

export default App;
